import SwiftUI

/// Action-row glyphs traced from the reference screenshots at 8× and reduced to
/// 1:1 outline data. They are not SF Symbols: the reference uses its own set,
/// and the shapes carry the weight the icons need at 12–14pt.
///
/// Coordinates are in points, origin at the icon's tight bounding box, filled
/// with the even-odd rule. The colour comes from the caller.
struct TracedIcon {
    let size: CGSize
    /// Each contour is a closed polygon as `x,y,x,y,…` in points.
    let contours: [[CGFloat]]
}

struct TracedIconShape: Shape {
    let icon: TracedIcon

    func path(in rect: CGRect) -> Path {
        var path = Path()
        let sx = rect.width / icon.size.width
        let sy = rect.height / icon.size.height
        for contour in icon.contours where contour.count >= 6 {
            path.move(to: CGPoint(x: rect.minX + contour[0] * sx, y: rect.minY + contour[1] * sy))
            var i = 2
            while i + 1 < contour.count {
                path.addLine(to: CGPoint(x: rect.minX + contour[i] * sx, y: rect.minY + contour[i + 1] * sy))
                i += 2
            }
            path.closeSubpath()
        }
        return path
    }
}

struct TracedIconView: View {
    let icon: TracedIcon
    var color: Color

    var body: some View {
        TracedIconShape(icon: icon)
            .fill(color, style: FillStyle(eoFill: true))
            .frame(width: icon.size.width, height: icon.size.height)
            .accessibilityHidden(true)
    }
}

